} from 'lucide-react';
import { Ticket, TicketStatus, Priority, Category } from '../types';
import { analyzeTicketDescription } from '../geminiService';

interface TicketsViewProps {
  tickets: Ticket[];
}

const TicketsView: React.FC<TicketsViewProps> = ({ tickets }) => {
  const [analyzingId, setAnalyzingId] = useState<string | null>(null);
  const [analysisResult, setAnalysisResult] = useState<any>(null);

  const handleAnalyze = async (ticket: Ticket) => {
    setAnalyzingId(ticket.id);
    const result = await analyzeTicketDescription(ticket.description);
    setAnalysisResult(result);
    // Auto-reset analysis after a while or when closing modal (simulated for now)
    setTimeout(() => {
      if (confirm(`IA Analisou: ${result.suggestedCategory} - ${result.suggestedPriority}\n\nJustificativa: ${result.justification}\n\nReferência ITIL: ${result.itilReference}\n\nDeseja aplicar?`)) {
        alert("Chamado atualizado com recomendações de IA.");
      }
      setAnalyzingId(null);
    }, 500);
  };

  const getStatusStyle = (status: TicketStatus) => {
    switch (status) {
      case TicketStatus.OPEN: return 'bg-sky-50 text-sky-700 border-sky-100';
      case TicketStatus.IN_PROGRESS: return 'bg-indigo-50 text-indigo-700 border-indigo-100';
      case TicketStatus.RESOLVED: return 'bg-emerald-50 text-emerald-700 border-emerald-100';
      case TicketStatus.PENDING: return 'bg-amber-50 text-amber-700 border-amber-100';
      default: return 'bg-slate-50 text-slate-700 border-slate-100';
    }
  };

  const getPriorityStyle = (priority: Priority) => {
    switch (priority) {
      case Priority.CRITICAL: return 'text-red-600 bg-red-50';
      case Priority.HIGH: return 'text-orange-600 bg-orange-50';
      case Priority.MEDIUM: return 'text-indigo-600 bg-indigo-50';
