                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center space-x-2 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button 
                        onClick={() => handleAnalyze(ticket)}
                        disabled={analyzingId === ticket.id}
                        className="p-2 text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors flex items-center space-x-1"
                        title="Análise IA"
                      >
                        {analyzingId === ticket.id ? <div className="animate-spin rounded-full h-4 w-4 border-2 border-indigo-600 border-t-transparent" /> : <BrainCircuit size={18} />}
                      </button>
                      <button className="p-2 text-slate-400 hover:bg-slate-100 rounded-lg transition-colors">
                        <Eye size={18} />
                      </button>
                      <button className="p-2 text-slate-400 hover:bg-slate-100 rounded-lg transition-colors">
                        <MoreHorizontal size={18} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default TicketsView;

import { GoogleGenAI, Type } from "@google/genai";
import { Category, Priority } from "./types";

// Always use process.env.API_KEY directly for initialization
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeTicketDescription = async (description: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analise o seguinte chamado de TI e recomende uma categoria (Incident, Request, Change, Problem, Project, Development) e uma prioridade (Low, Medium, High, Critical) baseada nos frameworks ITIL e COBIT.

      Chamado: "${description}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            suggestedCategory: { type: Type.STRING },
            suggestedPriority: { type: Type.STRING },
            justification: { type: Type.STRING },
            itilReference: { type: Type.STRING }
          },
          required: ["suggestedCategory", "suggestedPriority", "justification", "itilReference"]
        }
      }
    });

    // Accessing response.text property directly
    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return null;
  }
};

