import React, { useState, useMemo } from 'react';
import { 
  Filter, 
  Search, 
  MoreHorizontal, 
  Eye, 
  BrainCircuit,
  Clock,
  LayoutGrid,
  List,
  Building2,
  X,
  Trash2,
  CheckCircle,
  AlertCircle
} from 'lucide-react';
import { Ticket, TicketStatus, Priority, Category } from '../types';
import { analyzeTicketDescription } from '../geminiService';

interface TicketsViewProps {
  tickets: Ticket[];
  onUpdate: (id: string, updates: Partial<Ticket>) => void;
  onDelete: (id: string) => void;
